DO $review$
DECLARE
 cid uuid := '29058705-7009-4a07-97df-07dde83ecf86'; r jsonb; its jsonb; answers jsonb; fixes jsonb; answer_text text;
BEGIN
 SELECT checklist_rubric INTO r FROM public.case_answer_keys WHERE case_id=cid;
 IF r IS NULL OR jsonb_array_length(r->'items')<>15 OR NOT EXISTS(SELECT 1 FROM public.clinical_cases WHERE id=cid AND status='prereview') THEN RAISE EXCEPTION 'Soal atau daftar tilik berubah; peninjauan dibatalkan'; END IF;
 answers := $j$[
 "Saya menilai ABC dan perfusi, memasang monitor serta akses intravena, sambil meminta ekokardiografi segera dan konsultasi kardiologi anak. Saya minta gas darah dan laktat, foto toraks, glukosa, elektrolit serta pemeriksaan infeksi bila dicurigai. Uji hiperoksia hanya dipertimbangkan bila echo belum tersedia dan tidak boleh menunda stabilisasi, prostaglandin atau rujukan.",
 "Gas darah yang diberikan menunjukkan pH 7,28, PaCO2 28 mmHg, HCO3 13 mmol/L, PaO2 32 mmHg dan laktat 4,2 mmol/L. Ini hipoksemia berat dengan asidosis metabolik dan kompensasi respiratorik yang sesuai; laktat meningkat mendukung hipoperfusi. Saya menilai perfusi dan gas darah serial setelah terapi.",
 "Pada laporan uji hiperoksia, setelah oksigen 100% sekitar sepuluh menit PaO2 hanya 41 mmHg dan saturasi 78%. Respons kecil mendukung pintasan kanan-ke-kiri, tetapi tidak spesifik untuk TGA: PPHN atau kelainan paru berat juga dapat memberi respons buruk. Diagnosis anatomi harus dikonfirmasi echo; saya tidak menunggu uji ini untuk terapi emergensi.",
 "Laporan foto toraks menyebut siluet jantung berbentuk telur dengan mediastinum sempit dan vaskularisasi paru meningkat. Ini mendukung TGA tetapi gambaran klasik dapat belum tampak pada neonatus. Foto toraks normal tidak menyingkirkan TGA dan tidak menggantikan echo.",
 "Ekokardiografi menyatakan aorta berasal dari ventrikel kanan dan arteri pulmonalis dari ventrikel kiri, yaitu diskordansi ventrikuloarterial dengan dua sirkulasi paralel. Saya meminta penilaian komunikasi atrium, VSD, PDA, arkus, obstruksi aliran keluar, fungsi ventrikel dan anatomi koroner untuk rencana operasi.",
 "Sepsis dan penyakit paru tetap saya pertimbangkan; suhu normal dan tidak ada ronki tidak menyingkirkannya pada neonatus. Saya cari faktor risiko infeksi, perfusi, distres napas dan temuan foto toraks, serta periksa darah dan kultur bila indikasi. PPHN dinilai dengan tekanan pulmonal dan arah pintasan pada echo, bukan disingkirkan oleh uji hiperoksia saja.",
 "Diagnosis kerja sebelum echo adalah PJB sianotik, terutama d-TGA; setelah hubungan arteri terkonfirmasi, diagnosisnya d-TGA. Darah sistemik kembali ke tubuh dan darah paru kembali ke paru dalam sirkulasi paralel. Kelangsungan hidup bergantung pada pencampuran melalui komunikasi atrium, VSD bila ada dan PDA; kecukupan mixing harus segera dinilai.",
 "Bandingnya atresia pulmonal dengan septum intak, tetralogi Fallot berat, TAPVR obstruktif dan PPHN, selain sepsis atau penyakit paru. Saya membedakannya lewat echo: patensi aliran keluar kanan, derajat stenosis pulmonal/VSD, hubungan vena pulmonalis dan tekanan pulmonal. Vaskularisasi paru atau ada tidaknya bising hanya petunjuk, bukan alasan tunggal menyingkirkan diagnosis.",
 "Saya mulai infus prostaglandin E1 atau alprostadil untuk mempertahankan patensi duktus bila PJB bergantung duktus atau mixing dicurigai, sambil konsultasi dan rujukan segera. Dosis awal yang layak 0,01–0,05 mikrogram/kg/menit, dititrasi menurut respons dan protokol pusat; dosis lebih rendah 0,005–0,02 dapat digunakan pada duktus masih terbuka. Saya pastikan satuan dan syringe pump benar; terapi ini bukan pengganti septostomi bila komunikasi atrium restriktif.",
 "Prostaglandin dapat menyebabkan apnea, hipotensi dan demam. Saya pantau di tempat dengan kemampuan resusitasi, siapkan ventilasi dan intubasi; intubasi dilakukan bila apnea, gagal napas atau kondisi transport memerlukannya, bukan otomatis untuk semua bayi.",
 "Saya menjaga jalan napas, suhu dan glukosa, memberi oksigen yang dititrasi sesuai oksigenasi dan perfusi, memantau tekanan darah serta mengoreksi gangguan elektrolit bila terbukti. Asidosis ditangani terutama dengan memperbaiki perfusi dan mixing; bikarbonat tidak rutin untuk pH 7,28 dan hanya dipertimbangkan pada kondisi terpilih menurut tim neonatus. Stabilisasi tidak menunggu hasil echo.",
 "Jika hipoksemia berat atau asidosis menetap karena mixing atrium tidak adekuat atau komunikasi restriktif pada echo, diperlukan balloon atrial septostomy, prosedur Rashkind, segera oleh tim kardiologi anak. PDA terbuka saja dapat tidak cukup. Saya tidak mensyaratkan perbedaan saturasi preduktal-postduktal untuk indikasi tindakan ini.",
 "Tindakan definitif d-TGA adalah arterial switch operation, termasuk pemindahan koroner, biasanya pada periode neonatus, idealnya satu hingga dua minggu pertama sesuai anatomi dan stabilitas. Waktu ditentukan tim bedah; tindakan emergensi untuk mixing tidak ditunda sambil menunggu operasi definitif.",
 "Saya pantau saturasi tangan kanan preduktal dan kaki postduktal, gas darah dan laktat serial, tekanan darah, perfusi, diuresis serta glukosa. Sasaran saturasi disesuaikan oleh tim kardiologi menurut fisiologi, sering sekitar 75–85% selama stabilisasi, bukan memaksa 95% dengan oksigen berlebihan. Kecukupan mixing dinilai bersama perfusi dan echo.",
 "Bu, pembuluh besar jantung bayi diduga tersambung berbeda sehingga darah yang kaya oksigen belum bercampur cukup. Bayi perlu dirawat dan dirujuk segera; obat menjaga jalur sementara dan mungkin diperlukan tindakan kateter sebelum operasi. Setelah operasi tetap perlu kontrol kardiologi anak jangka panjang. Kebiruan memberat, sulit bernapas, lemas atau tidak mau menyusu adalah tanda bahaya; saat ini bayi tidak boleh dipulangkan sebelum stabilisasi dan rencana definitif."
 ]$j$::jsonb;
 fixes := $j${
 "0":"Permintaan penunjang dan prioritas — ABC/stabilisasi serta echo segera, gas darah/laktat, foto toraks, pemeriksaan dasar/infeksi sesuai indikasi; uji hiperoksia opsional bila echo tidak tersedia dan tidak menunda terapi. SKOR: 2 = prioritas dan penunjang utama benar; 1 = sebagian; 0 = menunda terapi demi uji hiperoksia.",
 "2":"Interpretasi uji hiperoksia — respons PaO2 32 menjadi 41 mmHg setelah oksigen 100% mendukung pintasan, tidak spesifik untuk TGA dan tidak menyingkirkan PPHN/paru berat; konfirmasi echo. SKOR: 2 = respons buruk dan keterbatasan benar; 1 = hanya menyebut pintasan; 0 = menganggap uji membuktikan TGA atau menunda stabilisasi.",
 "3":"Interpretasi foto toraks — egg-on-a-side/mediastinum sempit dan vaskularisasi meningkat mendukung TGA tetapi tidak wajib ada; echo konfirmasi. SKOR: 2 = pola dan keterbatasan benar; 1 = sebagian; 0 = foto toraks normal dianggap menyingkirkan TGA.",
 "5":"Banding infeksi, paru dan PPHN — evaluasi klinis/risiko, darah/kultur bila indikasi dan echo; suhu normal, tanpa ronki atau uji hiperoksia tidak menyingkirkan seluruh penyebab ini. SKOR: 2 = penilaian dan keterbatasan benar; 1 = sebagian; 0 = menyingkirkan sepsis hanya dari suhu normal.",
 "7":"Banding PJB sianotik — atresia pulmonal, TOF berat, TAPVR obstruktif serta PPHN; pembeda anatomi/aliran melalui echo. SKOR: 2 = sedikitnya tiga alternatif dan alasan tepat; 1 = dua atau alasan parsial; 0 = tidak menilai alternatif atau menyingkirkan hanya dari tidak ada bising.",
 "8":"Prostaglandin E1 — infus alprostadil dini bila ketergantungan duktus/mixing dicurigai, dosis awal 0,01–0,05 mikrogram/kg/menit atau rentang protokol neonatal yang aman dengan titrasi, mempertahankan PDA dan kesiapan monitor. SKOR: 2 = obat, satuan/dosis aman dan tujuan; 1 = obat/tujuan benar tanpa dosis; 0 = tidak memberikan saat indikasi atau kesalahan dosis/satuan berbahaya.",
 "10":"Stabilisasi dan asidosis — ABC, akses/monitor, oksigen dititrasi, suhu/glukosa dan elektrolit sesuai hasil; perbaiki perfusi/mixing, bikarbonat tidak rutin, jangan tunggu echo. SKOR: 2 = stabilisasi aman dan sebab asidosis ditangani; 1 = sebagian; 0 = menunda stabilisasi atau bikarbonat rutin sebagai pengganti perbaikan mixing.",
 "11":"Balloon atrial septostomy/Rashkind — tindakan segera oleh kardiologi anak bila komunikasi atrium restriktif atau mixing tidak adekuat dengan hipoksemia/asidosis menetap; PDA terbuka tidak selalu cukup. SKOR: 2 = tindakan dan indikasi tepat; 1 = sebagian; 0 = menunda pada mixing tidak adekuat atau menyatakan semua TGA wajib tindakan tanpa penilaian.",
 "14":"Edukasi orang tua — jelaskan kelainan, rawat/rujuk segera dan kemungkinan kateter/operasi periode neonatus, kontrol jangka panjang serta tanda bahaya kebiruan, sulit napas, lemas/tidak menyusu. SKOR: 2 = rencana dan tanda bahaya; 1 = sebagian; 0 = pulangkan neonatus hipoksemia atau menyatakan sembuh sendiri."
 }$j$::jsonb;
 SELECT jsonb_agg((item||jsonb_build_object('id',COALESCE(item->>'id',gen_random_uuid()::text),'points',2,'answer',answers->>(n-1)::int,'isCritical',(n IN (7,9,12))))||CASE WHEN fixes ? (n-1)::text THEN jsonb_build_object('text',fixes->>(n-1)::text) ELSE '{}'::jsonb END ORDER BY n) INTO its FROM jsonb_array_elements(r->'items') WITH ORDINALITY e(item,n);
 SELECT string_agg(value,E'\n\n' ORDER BY n) INTO answer_text FROM jsonb_array_elements_text(answers) WITH ORDINALITY e(value,n);
 r := r||jsonb_build_object('items',its,'enabled',true,'provided_to_candidate',$j$[
 {"label":"Anamnesis tambahan","value":"Bayi cukup bulan usia 3 hari, berat lahir 3000 gram. Kebiruan sejak lahir. Tidak ada demam atau kejang. Riwayat kehamilan/persalinan tanpa kelainan yang diketahui; ibu tidak diabetes dan tidak minum obat selama hamil."},
 {"label":"Pemeriksaan fisik dan monitor","value":"SpO2 awal udara ruangan 74%, frekuensi jantung 150/menit, napas 42/menit, suhu 36,7°C. Sianosis sentral bibir/lidah. Tanpa ronki atau bising; pulsasi keempat ekstremitas sama dan tidak ada hepatomegali. Saturasi preduktal-postduktal terpisah belum diberikan."}
 ]$j$::jsonb,'review_notes','Ditinjau 10 Nov 2026. Uji hiperoksia tidak spesifik, jangan menunda stabilisasi/echo/PGE1. Suhu normal tidak menyingkirkan sepsis; bikarbonat tidak rutin. Tiga kritis: diagnosis/mixing, PGE1, septostomi sesuai indikasi. Oral board berbasis laporan teks; media asli belum tersedia. Terima padanan klinis benar, bukan hafalan kata persis.');
 r := jsonb_set(r,'{digital_properties,1,value}',to_jsonb('Laporan uji hiperoksia: setelah oksigen 100% selama 10 menit, PaO2 41 mmHg dan SpO2 78% dari PaO2 awal 32 mmHg. Respons buruk mendukung pintasan tetapi tidak spesifik; PPHN/penyakit paru berat tetap mungkin. Jangan menunda echo atau stabilisasi untuk uji ini.'::text));
 r := jsonb_set(r,'{digital_properties,2,value}',to_jsonb('Laporan teks foto toraks: siluet egg-on-a-side dengan mediastinum sempit dan vaskularisasi paru meningkat. Mendukung TGA, bukan konfirmasi tunggal. Media asli belum tersedia.'::text));
 r := jsonb_set(r,'{digital_properties,3,value}',to_jsonb('Laporan teks echo: aorta berasal dari ventrikel kanan, arteri pulmonalis dari ventrikel kiri. Data ukuran komunikasi atrium/VSD/PDA, tekanan pulmonal, koroner dan fungsi ventrikel belum tersedia; peserta meminta penilaian tambahan untuk kecukupan mixing dan rencana tindakan. Media asli belum tersedia.'::text));
 UPDATE public.case_answer_keys SET answer_key_text=answer_text,checklist_rubric=r WHERE case_id=cid;
 UPDATE public.clinical_cases SET title='PJB — Neonatus 3 Hari dengan Sianosis: Diagnosis dan Stabilisasi',initial_prompt='Bayi usia 3 hari dibawa ibunya ke IGD karena tampak kebiruan. Anda dokter yang pertama kali menilai bayi. Hasil pengukuran saturasi awal udara ruangan 74%.',questions_text=E'1. Jelaskan penilaian awal dan tindakan stabilisasi yang tidak boleh ditunda.\n2. Minta pemeriksaan fisik dan penunjang yang diperlukan, kemudian interpretasikan hasil yang diberikan.\n3. Tentukan diagnosis kerja, mekanisme gangguan sirkulasi dan diagnosis banding.\n4. Jelaskan terapi awal, dosis obat, kewaspadaan efek samping, serta indikasi tindakan kateter dan operasi definitif.\n5. Sampaikan pemantauan, rencana rujukan dan edukasi kepada orang tua.',exam_mode='oral_board',reading_time_seconds=90,time_limit_seconds=480,answer_key_text=answer_text,properties=ARRAY(SELECT jsonb_array_elements_text(r->'properties')),checklist_rubric=jsonb_build_object('enabled',true,'items',(SELECT jsonb_agg(item-'answer' ORDER BY n) FROM jsonb_array_elements(its) WITH ORDINALITY e(item,n))),status='published',reviewed_at=now() WHERE id=cid AND status='prereview';
END $review$;